action.code:
if (ckh == nullptr || tabind == nullptr) {
    return true;
}

const size_t nbuckets = ckh->nbuckets;
while (*tabind < nbuckets) {
    ckh_t::bucket_t& bucket = ckh->buckets[*tabind];
    if (!bucket.empty()) {
        *key = bucket.key;
        *data = bucket.data;
        ++(*tabind);
        return false;
    }
    ++(*tabind);
}
return true;
// END_CODE

